#!/usr/bin/env python3
"""Exact post-overlay hardening. Does not approve cards or mark Phase 7 complete."""
from pathlib import Path
import base64,gzip,hashlib,json,subprocess,sys,tempfile
PAYLOAD=''''''
FILES=[('app/src/main/java/com/koenterprises/territorycardstudio/NativeSourceInspectionStore.kt','e05b8fe5fbc86023449e6da5f698ac171466125f378ec69c8dc68ee584d044cc','f4e9a778a910d053a594b595969cf3e755bff8b7099c6733e22b9f01169f35ca'),('app/src/androidTest/java/com/koenterprises/territorycardstudio/Phase7SourceSufficiencyInstrumentationTest.kt','74ad500e61d86c5881fe443746074339756f1e294c6cadca3c48056acfa0ab6f','dbd2811ebb986d2d6aa4b6684016f7d352e76075949eb072d6fcd877bfb76321')]
def main():
    if len(sys.argv)!=2:raise SystemExit('Usage: phase7-source-hardening.py <source-directory>')
    root=Path(sys.argv[1]).resolve(strict=True)
    patch=gzip.decompress(base64.b64decode(PAYLOAD,validate=True))
    assert hashlib.sha256(patch).hexdigest()=='e1048aca64ca1724c8ecd1e9da1c329d66f21311579a019fb4d96604fd3471db'
    for name,before,after in FILES:assert hashlib.sha256((root/name).read_bytes()).hexdigest()==before,('Baseline mismatch',name)
    with tempfile.NamedTemporaryFile(suffix='.patch') as f:
        f.write(patch);f.flush()
        command=['git','apply','--whitespace=error','--directory='+root.name]
        subprocess.run(command+['--check',f.name],cwd=root.parent,check=True)
        subprocess.run(command+[f.name],cwd=root.parent,check=True)
    for name,before,after in FILES:assert hashlib.sha256((root/name).read_bytes()).hexdigest()==after,('Result mismatch',name)
    out=root.parent/'evidence';out.mkdir(exist_ok=True)
    (out/'source-hardening-readable.patch').write_bytes(patch)
    print(json.dumps({'filesVerified':2,'sourceHoldRetainedAcrossReanalysis':True,'mixedSavedCandidateTestsAdded':True,'phase7Complete':False},indent=2))
if __name__=='__main__':main()
